namespace Yubico.YubiKit.OpenPgp.UnitTests;

public class AlgorithmAttributesTests
{
    [Theory]
    [InlineData(RsaSize.Rsa2048, 2048)]
    [InlineData(RsaSize.Rsa3072, 3072)]
    [InlineData(RsaSize.Rsa4096, 4096)]
    public void RsaAttributes_RoundTrip_PreservesValues(RsaSize keySize, int expectedNLen)
    {
        var attrs = RsaAttributes.Create(keySize);

        var bytes = attrs.ToBytes();
        var parsed = AlgorithmAttributes.Parse(bytes);

        var rsa = Assert.IsType<RsaAttributes>(parsed);
        Assert.Equal(0x01, rsa.AlgorithmId);
        Assert.Equal(expectedNLen, rsa.NLen);
        Assert.Equal(17, rsa.ELen);
        Assert.Equal(RsaImportFormat.Standard, rsa.ImportFormat);
    }

    [Fact]
    public void RsaAttributes_WithCrtFormat_RoundTrips()
    {
        var attrs = RsaAttributes.Create(RsaSize.Rsa2048, RsaImportFormat.Crt);

        var bytes = attrs.ToBytes();
        var parsed = AlgorithmAttributes.Parse(bytes);

        var rsa = Assert.IsType<RsaAttributes>(parsed);
        Assert.Equal(RsaImportFormat.Crt, rsa.ImportFormat);
    }

    [Fact]
    public void RsaAttributes_ToBytes_ProducesCorrectWireFormat()
    {
        var attrs = RsaAttributes.Create(RsaSize.Rsa2048);

        var bytes = attrs.ToBytes();

        // Algorithm=0x01, NLen=0x0800 (2048), ELen=0x0011 (17), ImportFormat=0x00
        Assert.Equal([0x01, 0x08, 0x00, 0x00, 0x11, 0x00], bytes);
    }

    [Fact]
    public void RsaAttributes_Parse_FromWireFormat()
    {
        // RSA 4096, exponent length 17 bits (e=65537), CRT format
        byte[] wire = [0x01, 0x10, 0x00, 0x00, 0x11, 0x02];
        var parsed = AlgorithmAttributes.Parse(wire);

        var rsa = Assert.IsType<RsaAttributes>(parsed);
        Assert.Equal(4096, rsa.NLen);
        Assert.Equal(17, rsa.ELen);
        Assert.Equal(RsaImportFormat.Crt, rsa.ImportFormat);
    }

    [Theory]
    [InlineData(CurveOid.Secp256R1, KeyRef.Sig, 0x13)]
    [InlineData(CurveOid.Secp384R1, KeyRef.Aut, 0x13)]
    [InlineData(CurveOid.Secp256R1, KeyRef.Dec, 0x12)]
    [InlineData(CurveOid.Ed25519, KeyRef.Sig, 0x16)]
    [InlineData(CurveOid.Ed25519, KeyRef.Aut, 0x16)]
    public void EcAttributes_Create_SetsCorrectAlgorithmId(CurveOid oid, KeyRef keyRef, int expectedAlgId)
    {
        var attrs = EcAttributes.Create(keyRef, oid);

        Assert.Equal(expectedAlgId, attrs.AlgorithmId);
        Assert.Equal(oid, attrs.Oid);
    }

    [Theory]
    [InlineData(CurveOid.Secp256R1)]
    [InlineData(CurveOid.Secp384R1)]
    [InlineData(CurveOid.Secp521R1)]
    [InlineData(CurveOid.BrainpoolP256R1)]
    [InlineData(CurveOid.Ed25519)]
    [InlineData(CurveOid.X25519)]
    public void EcAttributes_RoundTrip_PreservesOid(CurveOid oid)
    {
        var keyRef = oid == CurveOid.X25519 ? KeyRef.Dec : KeyRef.Sig;
        var attrs = EcAttributes.Create(keyRef, oid);

        var bytes = attrs.ToBytes();
        var parsed = AlgorithmAttributes.Parse(bytes);

        var ec = Assert.IsType<EcAttributes>(parsed);
        Assert.Equal(oid, ec.Oid);
    }

    [Fact]
    public void EcAttributes_WithPubkeyFormat_RoundTrips()
    {
        // Build raw bytes: algorithmId=0x13, OID bytes for Secp256R1, import format 0xFF
        var oidBytes = CurveOid.Secp256R1.GetOidBytes();
        var raw = new byte[1 + oidBytes.Length + 1];
        raw[0] = 0x13; // ECDSA
        oidBytes.CopyTo(raw.AsSpan(1));
        raw[^1] = (byte)EcImportFormat.StandardWithPubkey;
        var attrs = AlgorithmAttributes.Parse(raw);

        var bytes = attrs.ToBytes();
        var parsed = AlgorithmAttributes.Parse(bytes);

        var ec = Assert.IsType<EcAttributes>(parsed);
        Assert.Equal(CurveOid.Secp256R1, ec.Oid);
        Assert.Equal(EcImportFormat.StandardWithPubkey, ec.ImportFormat);
    }

    [Fact]
    public void Parse_UnknownAlgorithmId_Throws()
    {
        byte[] wire = [0xFF, 0x00, 0x00];
        Assert.Throws<ArgumentException>(() => AlgorithmAttributes.Parse(wire));
    }
}

using System.Security.Cryptography;
using Yubico.YubiKit.Core.Cryptography;
using Yubico.YubiKit.Core.Utilities;
using Yubico.YubiKit.Tests.Shared;

namespace Yubico.YubiKit.OpenPgp.UnitTests.AuditV2;

public sealed class OpenPgpAuditReproTests
{
    /// <summary>The import names its slot once: the template CRT is derived from keyRef, never supplied separately.</summary>
    [Theory]
    [InlineData(KeyRef.Sig, 0xB6)]
    [InlineData(KeyRef.Dec, 0xB8)]
    [InlineData(KeyRef.Aut, 0xA4)]
    [Trait("Audit", "YESDK-1634")]
    public async Task YESDK1634_ImportTargetsTheRequestedSlot(KeyRef keyRef, byte crtTag)
    {
        byte[] appData = ApplicationData();
        var connection = new RecordingSmartCardConnection(
            [0x90, 0x00], [0x05, 0x08, 0x00, 0x90, 0x00], appData,
            [0x90, 0x00], // algorithm attributes
            [0x90, 0x00], [0x90, 0x00], // import, chained in two short APDUs
            appData);
        await using var session = await OpenPgpSession.CreateAsync(connection,
            cancellationToken: TestContext.Current.CancellationToken);
        using var rsa = RSA.Create(2048);
        using var key = RSAPrivateKey.CreateFromParameters(rsa.ExportParameters(includePrivateParameters: true));

        await session.PutKeyAsync(keyRef, key, TestContext.Current.CancellationToken);

        byte[] attributes = Assert.Single(connection.TransmittedCommands, command => command[1] == 0xDA);
        Assert.Equal((byte)keyRef.AlgorithmAttributesDo(), attributes[3]);
        byte[] import = connection.TransmittedCommands.First(command => command[1] == 0xDB);
        // Short APDU (Lc at [4]); outer 4D with a two-byte length (82 LL LL); the CRT is the first child.
        Assert.Equal([0x4D, 0x82], import.AsSpan(5, 2).ToArray());
        Assert.Equal([crtTag, 0x00], import.AsSpan(9, 2).ToArray());
    }

    /// <summary>RFC 9580 §3.7.1.3: a count below salt+PIN still hashes one full copy; checked against a host hash.</summary>
    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(8)]
    [InlineData(9)]
    [InlineData(13)]
    [InlineData(14)]
    [Trait("Audit", "YESDK-1633")]
    [Trait("Audit", "YESDK-1634")]
    public void YESDK1633_ShortKdfCountStillHashesCompletePin(int count)
    {
        using var kdf = new KdfIterSaltedS2k
        {
            HashAlgorithm = KdfHashAlgorithm.Sha256,
            SaltUser = new byte[] { 1, 2, 3, 4, 5, 6, 7, 8 },
            IterationCount = count
        };
        byte[] expected = SHA256.HashData([1, 2, 3, 4, 5, 6, 7, 8, .. "123456"u8]);
        byte[] actual = kdf.Process(Pw.User, "123456"u8);
        try
        {
            Assert.Equal(expected, actual);
        }
        finally
        {
            CryptographicOperations.ZeroMemory(expected);
            CryptographicOperations.ZeroMemory(actual);
        }
    }

    /// <summary>The KDF-DO count is an unsigned 32-bit value; 0x80000000 is 2^31, not a negative number.</summary>
    [Theory]
    [InlineData(new byte[] { 0x80, 0, 0, 0 }, 2_147_483_648L)]
    [InlineData(new byte[] { 0xFF, 0xFF, 0xFF, 0xFF }, 4_294_967_295L)]
    [InlineData(new byte[] { 0x00, 0x78, 0, 0 }, 0x780000L)]
    [Trait("Audit", "YESDK-1633")]
    public void YESDK1633_UnsignedKdfCountDoesNotWrapNegative(byte[] countBytes, long expected)
    {
        byte[] encoded =
        [
            0x81, 1, 3, 0x82, 1, 8, 0x83, 4, .. countBytes,
            0x84, 8, 1, 2, 3, 4, 5, 6, 7, 8
        ];
        using var parsed = Kdf.Parse(encoded);
        var kdf = Assert.IsType<KdfIterSaltedS2k>(parsed);

        Assert.Equal(expected, kdf.IterationCount);
        Assert.Equal(countBytes, TlvHelper.DecodeDictionary(kdf.ToBytes())[0x83].ToArray());
    }

    /// <summary>One copy + 1 byte: the count is a byte count, so 15 hashes salt+PIN followed by the first salt byte.</summary>
    [Fact]
    [Trait("Audit", "YESDK-1633")]
    public void YESDK1633_CountOneAboveInputLength_HashesOneCopyAndOneByte()
    {
        using var kdf = new KdfIterSaltedS2k
        {
            HashAlgorithm = KdfHashAlgorithm.Sha256,
            SaltUser = new byte[] { 1, 2, 3, 4, 5, 6, 7, 8 },
            IterationCount = 15
        };
        byte[] expected = SHA256.HashData([1, 2, 3, 4, 5, 6, 7, 8, .. "123456"u8, 1]);

        Assert.Equal(expected, kdf.Process(Pw.User, "123456"u8));
    }

    /// <summary>Checks retained SHA-256 S2K vectors; this test executes the SDK derivation, not libgcrypt/GnuPG.</summary>
    [Theory]
    [InlineData(8, "1ae0f1043e1492a1acffc2319de52fa4713cf4bfd7123563345550f0da8eee9a")]
    [InlineData(100_000, "8fc77436ded3825377da921acc4fb1e0c619e426b926c30f06fbb428c6ac9701")]
    [Trait("Audit", "YESDK-1633")]
    public void YESDK1633_MatchesLibgcrypt(long count, string expectedHex)
    {
        using var kdf = new KdfIterSaltedS2k
        {
            HashAlgorithm = KdfHashAlgorithm.Sha256,
            SaltUser = new byte[] { 1, 2, 3, 4, 5, 6, 7, 8 },
            IterationCount = count
        };

        Assert.Equal(Convert.FromHexString(expectedHex), kdf.Process(Pw.User, "123456"u8));
    }

    private static byte[] ApplicationData()
    {
        // Application-related data requires all three algorithm attributes and PIN status.
        using var aid = new Tlv(0x4F, [0xD2, 0x76, 0, 1, 0x24, 1, 3, 4, 0, 6, 0x12, 0x34, 0x56, 0x78]);
        using var capabilities = new Tlv(0xC0, [0x75, 0, 0, 0xFF, 4, 0x80, 0, 0xFF, 0, 0]);
        byte[] rsa = [1, 8, 0, 0, 0x11, 0];
        using var sig = new Tlv(0xC1, rsa);
        using var dec = new Tlv(0xC2, rsa);
        using var aut = new Tlv(0xC3, rsa);
        using var pw = new Tlv(0xC4, [0, 0x7F, 0x7F, 0x7F, 3, 0, 3]);
        using var fingerprints = new Tlv(0xC5, new byte[60]);
        using var caFingerprints = new Tlv(0xC6, new byte[60]);
        using var generationTimes = new Tlv(0xCD, new byte[12]);
        using var discretionary = new Tlv(0x73,
            [.. capabilities.AsSpan(), .. sig.AsSpan(), .. dec.AsSpan(), .. aut.AsSpan(),
                .. pw.AsSpan(), .. fingerprints.AsSpan(), .. caFingerprints.AsSpan(), .. generationTimes.AsSpan()]);
        using var outer = new Tlv(0x6E, [.. aid.AsSpan(), .. discretionary.AsSpan()]);
        return [.. outer.AsSpan(), 0x90, 0x00];
    }
}

